//! Instructions and accounts of the `cota_v2` program, using the types generated by Anchor.
//!
//! Program v1 (`4FCh…`) is no longer written to: its ledger is a frozen archive (tag `v1-final` has the
//! tools that spoke to it).

use anchor_lang::{
    prelude::Pubkey,
    solana_program::{instruction::Instruction, system_program},
    AccountDeserialize, InstructionData, ToAccountMetas,
};
use anyhow::{Context, Result};
use cota_core::precompile::ed25519_instruction_data;
use cota_ingest::config::StationConfig;
use cota_v2::{accounts as acc, instruction as ix};

pub use cota_v2::{
    ForecastArgs, OutlookRuleArgs, Payout, Record, Registry, TriggerProof, Vault, VaultArgs, ID as PROGRAM_ID,
    TRIGGER_EARLY_WARNING, TRIGGER_FLOW_ALERT,
};

use crate::PROTOCOL;

pub fn registry_pda() -> Pubkey {
    Pubkey::find_program_address(&[cota_v2::REGISTRY_SEED], &PROGRAM_ID).0
}

pub fn alert_rule_pda(station_id: &str) -> Pubkey {
    Pubkey::find_program_address(&[cota_v2::ALERT_RULE_SEED, station_id.as_bytes()], &PROGRAM_ID).0
}

pub fn outlook_rule_pda(region: &str) -> Pubkey {
    Pubkey::find_program_address(&[cota_v2::OUTLOOK_RULE_SEED, region.as_bytes()], &PROGRAM_ID).0
}

pub fn vault_pda(creator: &Pubkey, vault_id: u64) -> Pubkey {
    Pubkey::find_program_address(&[cota_v2::VAULT_SEED, creator.as_ref(), &vault_id.to_le_bytes()], &PROGRAM_ID).0
}

pub fn payout_pda(vault: &Pubkey, trigger_leaf: &[u8; 32]) -> Pubkey {
    Pubkey::find_program_address(&[cota_v2::PAYOUT_SEED, vault.as_ref(), trigger_leaf], &PROGRAM_ID).0
}

/// The program's ProgramData account, which holds its upgrade authority (the admin).
pub fn program_data_pda() -> Pubkey {
    Pubkey::find_program_address(&[PROGRAM_ID.as_ref()], &solana_sdk_ids::bpf_loader_upgradeable::ID).0
}

/// Accounts of the admin-only instructions: signed by the program's upgrade authority (the Squads vault on
/// devnet, through a multisig proposal), not by the operator.
fn admin_only(admin: Pubkey) -> Vec<anchor_lang::solana_program::instruction::AccountMeta> {
    acc::AdminOnly { admin, registry: registry_pda(), program: PROGRAM_ID, program_data: program_data_pda() }.to_account_metas(None)
}

fn authority_only(authority: Pubkey) -> Vec<anchor_lang::solana_program::instruction::AccountMeta> {
    acc::AuthorityOnly { authority, registry: registry_pda() }.to_account_metas(None)
}

fn committee_signed(submitter: Pubkey) -> Vec<anchor_lang::solana_program::instruction::AccountMeta> {
    acc::CommitteeSigned { submitter, registry: registry_pda(), instructions: solana_instructions_sysvar::ID }
        .to_account_metas(None)
}

/// The Ed25519 precompile instruction with the committee's signatures over `message`. It must come right
/// before the instruction that uses it: the program reads the previous instruction.
fn ed25519(message: &[u8], signatures: &[([u8; 32], [u8; 64])]) -> Instruction {
    Instruction::new_with_bytes(solana_sdk_ids::ed25519_program::ID, &ed25519_instruction_data(message, signatures), vec![])
}

// ---- administration --------------------------------------------------------------------------------

pub fn init_registry_instruction(authority: Pubkey, members: Vec<Pubkey>, threshold: u8) -> Instruction {
    Instruction::new_with_bytes(
        PROGRAM_ID,
        &ix::InitRegistry { members, threshold }.data(),
        acc::InitRegistry { authority, registry: registry_pda(), system_program: system_program::ID }.to_account_metas(None),
    )
}

/// Admin only.
pub fn set_authority_instruction(admin: Pubkey, new_authority: Pubkey) -> Instruction {
    Instruction::new_with_bytes(PROGRAM_ID, &ix::SetAuthority { new_authority }.data(), admin_only(admin))
}

/// Admin only.
pub fn rotate_member_instruction(admin: Pubkey, old: Pubkey, new: Pubkey) -> Instruction {
    Instruction::new_with_bytes(PROGRAM_ID, &ix::RotateMember { old, new }.data(), admin_only(admin))
}

pub fn register_station_instruction(authority: Pubkey, st: &StationConfig) -> Instruction {
    let station = cota_v2::StationArgs {
        station_id: st.id.clone(),
        name: st.name.clone(),
        source: st.source as u8,
        variable: st.variable as u8,
        lat_e6: (st.lat * 1e6).round() as i32,
        lon_e6: (st.lon * 1e6).round() as i32,
        datum_id: st.datum_id.clone(),
    };
    Instruction::new_with_bytes(PROGRAM_ID, &ix::RegisterStation { station }.data(), authority_only(authority))
}

/// Admin only.
pub fn set_alert_rule_instruction(admin: Pubkey, station_id: &str, threshold_milli: i64, level: u8) -> Instruction {
    Instruction::new_with_bytes(
        PROGRAM_ID,
        &ix::SetAlertRule { station_id: station_id.to_string(), threshold_milli, level }.data(),
        acc::SetAlertRule {
            admin,
            registry: registry_pda(),
            program: PROGRAM_ID,
            program_data: program_data_pda(),
            rule: alert_rule_pda(station_id),
            system_program: system_program::ID,
        }
        .to_account_metas(None),
    )
}

/// Admin only.
pub fn set_outlook_rule_instruction(admin: Pubkey, args: OutlookRuleArgs) -> Instruction {
    let rule = outlook_rule_pda(&args.region);
    Instruction::new_with_bytes(
        PROGRAM_ID,
        &ix::SetOutlookRule { args }.data(),
        acc::SetOutlookRule {
            admin,
            registry: registry_pda(),
            program: PROGRAM_ID,
            program_data: program_data_pda(),
            rule,
            system_program: system_program::ID,
        }
        .to_account_metas(None),
    )
}

// ---- records -----------------------------------------------------------------------------------------

pub fn to_program_header(h: &cota_core::BatchHeader) -> cota_v2::BatchHeader {
    cota_v2::BatchHeader {
        batch_id: h.batch_id,
        t_start: h.t_start,
        t_end: h.t_end,
        leaf_count: h.leaf_count,
        merkle_root: h.merkle_root,
        station_set_hash: h.station_set_hash,
        prev_batch_root: h.prev_batch_root,
    }
}

/// `[Ed25519 precompile with the signatures, commit_batch(header)]`.
pub fn commit_batch_instructions(
    submitter: Pubkey,
    header: &cota_core::BatchHeader,
    signatures: &[([u8; 32], [u8; 64])],
) -> [Instruction; 2] {
    [
        ed25519(&header.signing_message_for(PROTOCOL), signatures),
        Instruction::new_with_bytes(
            PROGRAM_ID,
            &ix::CommitBatch { header: to_program_header(header) }.data(),
            committee_signed(submitter),
        ),
    ]
}

pub fn report_degradation_instruction(authority: Pubkey, batch_id: u64, station_id: &str, score_milli: u16, reason: u8) -> Instruction {
    Instruction::new_with_bytes(
        PROGRAM_ID,
        &ix::ReportDegradation { batch_id, station_id: station_id.to_string(), score_milli, reason }.data(),
        authority_only(authority),
    )
}

/// The forecast and, if the station has an `AlertRule`, its alert, decided by the program.
pub fn commit_forecast_instruction(authority: Pubkey, args: ForecastArgs) -> Instruction {
    let rule = alert_rule_pda(&args.station_id);
    Instruction::new_with_bytes(
        PROGRAM_ID,
        &ix::CommitForecast { args }.data(),
        acc::CommitForecast { authority, registry: registry_pda(), rule }.to_account_metas(None),
    )
}

pub fn to_program_alert_header(h: &cota_core::PublicAlertHeader) -> cota_v2::PublicAlertHeader {
    cota_v2::PublicAlertHeader {
        issuer: h.issuer.clone(),
        alert_id: h.alert_id.clone(),
        content_sha256: h.content_sha256,
        severity: h.severity,
        onset: h.onset,
        expires: h.expires,
    }
}

pub fn record_public_alert_instructions(
    submitter: Pubkey,
    header: &cota_core::PublicAlertHeader,
    signatures: &[([u8; 32], [u8; 64])],
) -> [Instruction; 2] {
    [
        ed25519(&header.signing_message_for(PROTOCOL), signatures),
        Instruction::new_with_bytes(
            PROGRAM_ID,
            &ix::RecordPublicAlert { header: to_program_alert_header(header) }.data(),
            committee_signed(submitter),
        ),
    ]
}

pub fn to_program_outlook_header(h: &cota_core::OutlookHeader) -> cota_v2::OutlookHeader {
    cota_v2::OutlookHeader {
        region: h.region.clone(),
        issued_at: h.issued_at,
        window_end: h.window_end,
        models: h.models,
        rain_mean_milli: h.rain_mean_milli,
        rain_min_milli: h.rain_min_milli,
        rain_max_milli: h.rain_max_milli,
        content_sha256: h.content_sha256,
    }
}

pub fn commit_outlook_instructions(
    submitter: Pubkey,
    header: &cota_core::OutlookHeader,
    signatures: &[([u8; 32], [u8; 64])],
) -> [Instruction; 2] {
    [
        ed25519(&header.signing_message_for(PROTOCOL), signatures),
        Instruction::new_with_bytes(
            PROGRAM_ID,
            &ix::CommitOutlook { header: to_program_outlook_header(header) }.data(),
            acc::CommitOutlook {
                submitter,
                registry: registry_pda(),
                rule: outlook_rule_pda(&header.region),
                instructions: solana_instructions_sysvar::ID,
            }
            .to_account_metas(None),
        ),
    ]
}

// ---- vaults ------------------------------------------------------------------------------------------

pub fn create_vault_instruction(creator: Pubkey, args: VaultArgs) -> Instruction {
    let vault = vault_pda(&creator, args.vault_id);
    Instruction::new_with_bytes(
        PROGRAM_ID,
        &ix::CreateVault { args }.data(),
        acc::CreateVault { creator, vault, system_program: system_program::ID }.to_account_metas(None),
    )
}

pub fn trigger_payout_instruction(submitter: Pubkey, vault: Pubkey, beneficiary: Pubkey, proof: TriggerProof) -> Instruction {
    let payout = payout_pda(&vault, &cota_core::merkle::hash_leaf(&proof.record));
    Instruction::new_with_bytes(
        PROGRAM_ID,
        &ix::TriggerPayout { proof }.data(),
        acc::TriggerPayout { submitter, registry: registry_pda(), vault, beneficiary, payout, system_program: system_program::ID }
            .to_account_metas(None),
    )
}

pub fn close_vault_instruction(creator: Pubkey, vault: Pubkey) -> Instruction {
    Instruction::new_with_bytes(PROGRAM_ID, &ix::CloseVault {}.data(), acc::CloseVault { creator, vault }.to_account_metas(None))
}

// ---- accounts ----------------------------------------------------------------------------------------

pub fn decode_registry(data: &[u8]) -> Result<Registry> {
    Registry::try_deserialize(&mut &data[..]).context("invalid registry account")
}

pub fn decode_vault(data: &[u8]) -> Result<Vault> {
    Vault::try_deserialize(&mut &data[..]).context("invalid vault account")
}

pub fn decode_payout(data: &[u8]) -> Result<Payout> {
    Payout::try_deserialize(&mut &data[..]).context("invalid payout account")
}

pub fn decode_outlook_rule(data: &[u8]) -> Result<cota_v2::OutlookRule> {
    cota_v2::OutlookRule::try_deserialize(&mut &data[..]).context("invalid outlook rule account")
}

pub fn decode_alert_rule(data: &[u8]) -> Result<cota_v2::AlertRule> {
    cota_v2::AlertRule::try_deserialize(&mut &data[..]).context("invalid alert rule account")
}
